import { Mesh, PlaneGeometry, Group, CanvasTexture, RepeatWrapping, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec2, mix, smoothstep, uniform, time, texture, float, fract, noise, sub, mul, add } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, PlaneGeometry, Mesh } = THREE;
  const group = new Group();
  group.name = 'hub-collection-card-2-label';

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // --- Backdrop plane carrying engineered gradient (dark-first) ---
  const atlasRect = config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const planeW = 1.4;
  const planeH = (planeW * atlasRect.h) / atlasRect.w;

  const backdropGeo = new PlaneGeometry(planeW, planeH);

  // Load brushed-metal texture via ctx.textureLoader
  let brushTex = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    brushTex = tex;
    brushTex.wrapS = RepeatWrapping;
    brushTex.wrapT = RepeatWrapping;
    brushTex.repeat.set(1, 1);
    metalMat.map = brushTex;
    metalMat.needsUpdate = true;
  });

  // Engineered gradient + brushed metal + subtle grain via TSL nodes
  const vCoord = uv().y;
  const gradTop = vec3(colors.surface).rgb ?? vec3(0.043, 0.043, 0.063);
  const gradMid = vec3(colors.ink).rgb ?? vec3(0.086, 0.086, 0.114);
  const gradBot = vec3(0.03, 0.03, 0.045);
  const verticalGrad = mix(gradTop, gradMid, smoothstep(0.0, 0.55, vCoord));
  const fullGrad = mix(verticalGrad, gradBot, smoothstep(0.55, 1.0, vCoord));

  // Accent edge glow along left seam
  const seam = smoothstep(0.02, 0.0, uv().x);
  const accentVec = vec3(1.0, 0.165, 0.22);
  const accentGlow = mul(seam, 0.5);
  const baseColor = add(fullGrad, mul(accentVec, accentGlow));

  // Subtle grain via hash noise on uv
  const grain = sub(fract(mul(sin(mul(uv().xy, 12.9898)), 43758.5453)), 0.5);
  const grainAmt = 0.025;
  const withGrain = add(baseColor, mul(grain, grainAmt));

  const metalMat = new MeshStandardNodeMaterial({
    colorNode: withGrain,
    roughnessNode: float(0.62),
    metalnessNode: float(0.55),
    side: THREE.DoubleSide,
  });

  const backdrop = new Mesh(backdropGeo, metalMat);
  backdrop.position.set(0, 0, 0);
  group.add(backdrop);

  // Thin accent rule under the label
  const ruleGeo = new PlaneGeometry(planeW * 0.92, 0.012);
  const ruleMat = new MeshBasicNodeMaterial({
    colorNode: vec3(1.0, 0.165, 0.22),
    transparent: true,
    opacity: 0.85,
  });
  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, -planeH * 0.32, 0.002);
  group.add(rule);

  // --- Text content via ctx.fontAtlas ---
  const textGroup = new Group();
  for (const item of items) {
    const fontSize = item.typography?.fontSize ?? 39;
    const role = item.role ?? 'headline';
    const isHeadline = role === 'headline';
    const isCaption = role === 'caption';
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: colors.paper,
      align: 'left',
      letterSpacingPx: isCaption ? 1.6 : 0.4,
    });
    t.position.set(-planeW * 0.4, planeH * 0.18, 0.01);
    textGroup.add(t);
  }
  group.add(textGroup);

  // --- Light key + rim for product-shot grade (node-local, caps respected) ---
  const keyLight = new THREE.DirectionalLight(0xfff2e8, 1.1);
  keyLight.position.set(1.2, 1.8, 2.4);
  group.add(keyLight);

  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.6);
  rimLight.position.set(-1.6, 0.4, -1.4);
  group.add(rimLight);

  const fillLight = new THREE.AmbientLight(0x202028, 0.6);
  group.add(fillLight);

  // --- Entrance: weighted-settle (no linear) ---
  group.scale.set(0.96, 0.96, 0.96);
  group.userData._tl = gsap.timeline();
  group.userData._tl
    .to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' })
    .to(group.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' })
    .to(textGroup.position, { y: '+=0.04', duration: 0.5, ease: 'power2.out' }, 0)
    .fromTo(textGroup, { visible: false }, { visible: true, duration: 0.01 }, 0.2);

  // --- Cleanup ---
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    if (group.userData._tl) group.userData._tl.kill();
    backdropGeo.dispose();
    ruleGeo.dispose();
    metalMat.dispose();
    ruleMat.dispose();
    if (brushTex) brushTex.dispose();
    keyLight.dispose && keyLight.dispose();
    rimLight.dispose && rimLight.dispose();
    fillLight.dispose && fillLight.dispose();
  };

  return group;
}
